//nolint:gosmopolitan
package arc

import (
	"bytes"
	"encoding/binary"
	"errors"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"strings"
	"time"
)

const (
	marker = 0x1A // Special archive marker

	MethodOldStored byte = 1 // Old format uncompressed
	MethodStored    byte = 2 // Standard uncompressed
	MethodPacked    byte = 3 // Non-repeat RLE
	MethodSqueezed  byte = 4 // Huffman squeezing + RLE
	MethodCrunched5 byte = 5 // LZW old (uncrunched)
	MethodCrunched6 byte = 6 // LZW + RLE
	MethodCrunched7 byte = 7 // LZW + new hash + RLE
	MethodCrunched8 byte = 8 // Dynamic LZW + RLE
	MethodSquashed  byte = 9 // Squashed (13-bit dynamic LZW)
)

var (
	ErrCorruptLZW        = errors.New("corrupted crunched archive data")
	ErrCRCMismatch       = errors.New("crc-16 mismatch")
	ErrFormat            = errors.New("not a valid arc archive")
	ErrInvalidTree       = errors.New("file has an invalid decode tree")
	ErrUnsupportedMethod = errors.New("unsupported arc compression method")
)

// Header represents a file header inside an ARC archive.
type Header struct {
	Name             string
	Method           byte
	CompressedSize   uint32
	UncompressedSize uint32
	Modified         time.Time
	CRC              uint16
}

// File represents a file entry within an ARC archive.
type File struct {
	Header

	offset int64
	r      io.ReaderAt
}

// Open returns a ReadCloser that provides access to the uncompressed file contents.
func (f *File) Open() (io.ReadCloser, error) {
	const format = "file open %s: %w"
	sr := io.NewSectionReader(f.r, f.offset, int64(f.CompressedSize))
	b, err := decompress(f.Method, sr)
	if err != nil {
		return nil, fmt.Errorf(format, "decompress", err)
	}

	calcCRC := CRC16(b)
	if calcCRC != f.CRC {
		s := fmt.Sprintf("expected 0x%04X, got 0x%04X", f.CRC, calcCRC)
		return nil, fmt.Errorf(format, s, ErrCRCMismatch)
	}

	return io.NopCloser(bytes.NewReader(b)), nil
}

// Reader provides read access to the entries of an ARC archive.
type Reader struct {
	Files []*File
	r     io.ReaderAt
}

// NewReader returns a new Reader reading from r, which must have the given size.
func NewReader(r io.ReaderAt, size int64) (*Reader, error) {
	var files []*File
	offset := int64(0)

	for offset < size {
		file, nextOffset, done, err := readEntry(r, offset, len(files) > 0)
		if err != nil {
			return nil, err
		}
		if done {
			break
		}
		files = append(files, file)
		offset = nextOffset
	}

	if len(files) == 0 {
		return nil, ErrFormat
	}

	return &Reader{
		Files: files,
		r:     r,
	}, nil
}

const (
	headerLen    = 27
	headerOldLen = 23
	filenameLen  = 13
)

func readEntry(r io.ReaderAt, offset int64, hasFiles bool) (*File, int64, bool, error) {
	const format = "new reader %s: %w"

	var mark [1]byte
	_, err := r.ReadAt(mark[:], offset)
	if err != nil {
		if errors.Is(err, io.EOF) {
			return nil, offset, true, nil
		}
		return nil, offset, false, fmt.Errorf(format, "read at mark", err)
	}

	if mark[0] != marker {
		if hasFiles {
			return nil, offset, true, nil // trailing archive comment or padding
		}
		return nil, offset, false, ErrFormat
	}
	offset++

	var method [1]byte
	_, err = r.ReadAt(method[:], offset)
	if err != nil {
		return nil, offset, false, fmt.Errorf(format, "read at method", err)
	}
	offset++
	if method[0] == 0 {
		return nil, offset, true, nil // clean end of archive marker
	}

	l := headerLen
	if method[0] == MethodOldStored {
		l = headerOldLen
	}

	var raw [headerLen]byte
	_, err = r.ReadAt(raw[:l], offset)
	if err != nil {
		return nil, offset, false, fmt.Errorf(format, "read at raw", err)
	}
	offset += int64(l)

	hdr := parseHeader(method[0], raw[:l])
	file := &File{
		Header: hdr,
		offset: offset,
		r:      r,
	}
	nextOffset := offset + int64(hdr.CompressedSize)
	return file, nextOffset, false, nil
}

func parseHeader(method byte, b []byte) Header {
	name := parseFilename(b[:filenameLen])
	compSize := binary.LittleEndian.Uint32(b[13:17])
	dosDate := binary.LittleEndian.Uint16(b[17:19])
	dosTime := binary.LittleEndian.Uint16(b[19:21])
	crc := binary.LittleEndian.Uint16(b[21:23])

	uncompSize := compSize
	if method != MethodOldStored {
		uncompSize = binary.LittleEndian.Uint32(b[23:27])
	}

	return Header{
		Name:             name,
		Method:           method,
		CompressedSize:   compSize,
		UncompressedSize: uncompSize,
		Modified:         parseDOSTime(dosDate, dosTime),
		CRC:              crc,
	}
}

func parseFilename(b []byte) string {
	if i := bytes.IndexByte(b, 0); i >= 0 {
		b = b[:i]
	}
	return strings.TrimSpace(string(b))
}

// OpenReader opens the named ARC file and returns a Reader.
func OpenReader(name string) (*Reader, *os.File, error) {
	const format = "arc open reader: %w"
	f, err := os.Open(name)
	if err != nil {
		return nil, nil, fmt.Errorf(format, err)
	}
	st, err := f.Stat()
	if err != nil {
		_ = f.Close()
		return nil, nil, fmt.Errorf(format, err)
	}
	r, err := NewReader(f, st.Size())
	if err != nil {
		_ = f.Close()
		return nil, nil, fmt.Errorf(format, err)
	}
	return r, f, nil
}

// ExtractAll extracts all files from the ARC archive to dst directory.
func (r *Reader) ExtractAll(dst string, targets ...string) error {
	const format = "arc extract all %s: %w"
	targetSet := make(map[string]struct{}, len(targets))
	for _, t := range targets {
		targetSet[strings.ToLower(filepath.Base(t))] = struct{}{}
	}

	for _, f := range r.Files {
		if len(targetSet) > 0 {
			if _, ok := targetSet[strings.ToLower(f.Name)]; !ok {
				continue
			}
		}

		src, err := f.Open()
		if err != nil {
			return fmt.Errorf(format, "open entry "+f.Name, err)
		}

		name := filepath.Join(dst, filepath.Clean("/"+f.Name))
		const perm = 0o755
		err = os.MkdirAll(filepath.Dir(name), perm)
		if err != nil {
			_ = src.Close()
			return fmt.Errorf(format, "mkdir all", err)
		}

		dst, err := os.Create(name)
		if err != nil {
			_ = src.Close()
			return fmt.Errorf(format, "create "+name, err)
		}

		_, err = io.Copy(dst, src)
		_ = src.Close()
		_ = dst.Close()
		if err != nil {
			return fmt.Errorf(format, "write entry "+f.Name, err)
		}

		if !f.Modified.IsZero() {
			_ = os.Chtimes(name, f.Modified, f.Modified)
		}
	}
	return nil
}

func decompress(method byte, r io.Reader) ([]byte, error) {
	const format = "decompress %s: %w"
	switch method {
	case MethodOldStored, MethodStored:
		p, err := io.ReadAll(r)
		if err != nil {
			return nil, fmt.Errorf(format, "stored io read all", err)
		}
		return p, nil
	case MethodPacked:
		data, err := io.ReadAll(r)
		if err != nil {
			return nil, fmt.Errorf(format, "packed io read all", err)
		}
		return UnpackRLE(data), nil
	case MethodSqueezed:
		return Unsqueeze(r)
	case MethodCrunched5:
		return UncrunchLZW(r, false, false)
	case MethodCrunched6:
		return UncrunchLZW(r, false, true)
	case MethodCrunched7:
		return UncrunchLZW(r, true, true)
	case MethodCrunched8:
		return Uncrunch(r, false)
	case MethodSquashed:
		return Uncrunch(r, true)
	default:
		return nil, fmt.Errorf("method %d: %w", method, ErrUnsupportedMethod)
	}
}

func parseDOSTime(dateVal, timeVal uint16) time.Time {
	const (
		// Date offsets and masks
		yearBase   = 1980
		yearShift  = 9
		yearMask   = 0x7f // 7 bits (0-127)
		monthShift = 5
		monthMask  = 0x0f // 4 bits (1-12)
		dayMask    = 0x1f // 5 bits (1-31)
		// Time offsets and masks
		hourShift = 11
		hourMask  = 0x1f // 5 bits (0-23)
		minShift  = 5
		minMask   = 0x3f // 6 bits (0-59)
		secMask   = 0x1f // 5 bits (0-29, 2-second resolution)
		secStep   = 2
	)

	year := int((dateVal>>yearShift)&yearMask) + yearBase
	month := time.Month((dateVal >> monthShift) & monthMask)
	day := int(dateVal & dayMask)

	hr := int((timeVal >> hourShift) & hourMask)
	mn := int((timeVal >> minShift) & minMask)
	sc := int((timeVal & secMask) * secStep)

	if month < time.January || month > time.December || day < 1 || day > 31 {
		return time.Time{}
	}
	return time.Date(year, month, day, hr, mn, sc, 0, time.Local)
}

// CRC16 calculates the CRC-16 checksum used by SEA ARC archives
// using the 0xA001 reversed polynomial.
func CRC16(data []byte) uint16 {
	const poly = 0xA001
	var crc uint16
	for _, b := range data {
		crc ^= uint16(b)
		for range 8 {
			if (crc & 1) != 0 {
				crc = (crc >> 1) ^ poly
			} else {
				crc >>= 1
			}
		}
	}
	return crc
}
